[data-sidebar-row]:is([aria-label*=", Done"],[aria-label*=", Completed"],[aria-label*=", Woke"]) [data-slot="project-monogram"]{background:url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Cdefs%3E%3ClinearGradient id='r' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e2c070'/%3E%3Cstop offset='.5' stop-color='%238a6626'/%3E%3Cstop offset='1' stop-color='%233a2810'/%3E%3C/linearGradient%3E%3CradialGradient id='i' cx='.5' cy='.4'%3E%3Cstop offset='0' stop-color='%233a2a10'/%3E%3Cstop offset='1' stop-color='%230d0904'/%3E%3C/radialGradient%3E%3C/defs%3E%3Ccircle cx='12' cy='12' r='10.5' fill='url(%23r)' stroke='%23000'/%3E%3Ccircle cx='12' cy='12' r='8' fill='url(%23i)' stroke='%23000' stroke-width='.6'/%3E%3Ctext x='12' y='16.6' text-anchor='middle' font-family='Georgia,serif' font-weight='900' font-size='13' fill='%23ffd919' stroke='%235a3000' stroke-width='.5'%3E?%3C/text%3E%3C/svg%3E") center/contain no-repeat!important}
[data-sidebar-row]:is([aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label*=", Waiting"]) [data-slot="project-monogram"]{background:url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Cdefs%3E%3ClinearGradient id='p' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23f0c8ff'/%3E%3Cstop offset='.45' stop-color='%23b038e0'/%3E%3Cstop offset='1' stop-color='%235a0a7a'/%3E%3C/linearGradient%3E%3C/defs%3E%3Cpath d='M2.5 3 H21.5 L12 22 Z' fill='url(%23p)' stroke='%23000' stroke-linejoin='round'/%3E%3Cpath d='M12 7 V14 M12 16.5 V17.5' stroke='%23fff' stroke-width='2.4' stroke-linecap='round'/%3E%3C/svg%3E") center/contain no-repeat!important}
[data-sidebar-row]:is([aria-label*=", Failed"],[aria-label*=", Limited"]) [data-slot="project-monogram"]{background:url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23d8b060'/%3E%3Cstop offset='1' stop-color='%236a4812'/%3E%3C/linearGradient%3E%3ClinearGradient id='rd' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23a8261a'/%3E%3Cstop offset='1' stop-color='%234a0604'/%3E%3C/linearGradient%3E%3C/defs%3E%3Cpath d='M4 2 H20 V15 L12 22.5 L4 15 Z' fill='url(%23g)' stroke='%23000'/%3E%3Cpath d='M6 4 H18 V14 L12 19.8 L6 14 Z' fill='url(%23rd)'/%3E%3Cpath d='M12 6.5 V12.5 M12 15 V15.8' stroke='%23ffd8c8' stroke-width='2.2' stroke-linecap='round'/%3E%3C/svg%3E") center/contain no-repeat!important}
:is([data-testid="sidebar-pinned-header"],[data-testid="sidebar-working-header"],[data-testid="sidebar-settled-header"])>*{position:relative;margin:6px 10px 4px!important;min-height:20px;border-radius:4px!important;background:linear-gradient(#26211a,#1a1610)!important;box-shadow:inset 0 0 0 1px #000,inset 0 0 0 2px #4c4b4a,inset 0 0 0 3px #000!important;color:#fff!important;text-shadow:var(--az-sh)}
:is([data-testid="sidebar-pinned-header"],[data-testid="sidebar-working-header"],[data-testid="sidebar-settled-header"])>* *{color:#fff!important}
[data-testid="sidebar-project-folder"]{color:#fff!important;text-shadow:var(--az-sh)}
[data-slot="sidebar-footer"]{border-top:1px solid #000;box-shadow:inset 0 1px 0 #3a3632}
[data-slot="sidebar-inner"] [data-slot="input-control"]{background:#0a0908!important;border-radius:3px!important;box-shadow:inset 0 0 0 1px #000,inset 0 0 0 2px #4c4b4a!important;border:0!important}
[data-chat-header]{background:var(--az-grain),linear-gradient(#100e0d,#100e0d) padding-box,var(--az-stone) border-box!important;border:2px solid #0000!important;border-radius:4px!important;margin:0 10px;box-shadow:0 0 0 1px #000,0 4px 10px #000a!important}
nav[aria-label="Thread breadcrumb"] ol{gap:0!important}
nav[aria-label="Thread breadcrumb"] li[aria-hidden]{display:none!important}
nav[aria-label="Thread breadcrumb"] li:first-child{flex:none!important}
nav[aria-label="Thread breadcrumb"] li:first-child [data-slot="workspace-breadcrumb-text"]{max-width:none!important;overflow:visible!important}
nav[aria-label="Thread breadcrumb"] li>:is(button,h2){display:inline-flex;align-items:center;max-width:none!important;position:relative;height:26px!important;margin-right:-6px;padding:0 22px 0 20px!important;border-radius:0!important;background:#4c4b4a!important;clip-path:polygon(0 0,calc(100% - 11px) 0,100% 50%,calc(100% - 11px) 100%,0 100%,11px 50%);isolation:isolate}
nav[aria-label="Thread breadcrumb"] li>:is(button,h2)::before{content:"";position:absolute;inset:0 2px;z-index:-1;clip-path:polygon(0 0,calc(100% - 11px) 0,100% 50%,calc(100% - 11px) 100%,0 100%,11px 50%);background:linear-gradient(#26221e,#191714)}
nav[aria-label="Thread breadcrumb"] li:first-child>button{clip-path:polygon(0 0,calc(100% - 11px) 0,100% 50%,calc(100% - 11px) 100%,0 100%);padding-left:10px!important}
nav[aria-label="Thread breadcrumb"] li:first-child>button::before{inset:0 2px 0 0;clip-path:polygon(0 0,calc(100% - 11px) 0,100% 50%,calc(100% - 11px) 100%,0 100%);background:radial-gradient(90% 120% at 50% 100%,#8a2a0a,#5a1406 55%,#2a0802)}
nav[aria-label="Thread breadcrumb"] [data-slot="workspace-breadcrumb-text"]{color:var(--az-gold)!important;font:12.5px var(--az-ui)!important;text-shadow:var(--az-sh)}
nav[aria-label="Thread breadcrumb"] svg{color:var(--az-gold)!important}
nav[aria-label="Thread breadcrumb"] li>h2{flex:0 1 auto!important;width:auto!important;max-width:max-content!important;min-width:0}
nav[aria-label="Thread breadcrumb"] h2{color:var(--az-gold)!important;font:12.5px var(--az-ui)!important;text-shadow:var(--az-sh)}
[data-workspace-area="conversation"]{font-family:var(--az-ui)}
[data-user-message-bubble]{background:#100e0dee!important;border:0!important;border-radius:8px!important;box-shadow:inset 0 0 0 1px #000,inset 0 0 0 2px #4c4b4a,inset 0 0 0 3px #000,0 6px 14px #000b!important;color:#fff!important;text-shadow:0 1px 1px #000}
[data-user-message-bubble] *{color:#fff!important}
[data-user-message-bubble]::before{content:"To Claude:";display:block;padding:8px 14px 0;font:12px/1 var(--az-ui);color:#ff80ff;text-shadow:0 1px 1px #000}
[data-message-role="assistant"]{position:relative;margin-top:22px!important;padding:26px 4px 4px!important;overflow:visible!important}
[data-message-role="assistant"]::before{content:"Claude";position:absolute;top:0;left:0;right:0;height:22px;display:flex;align-items:center;justify-content:center;font:13px/1 var(--az-ui);color:var(--az-gold);text-shadow:var(--az-sh);background:var(--az-grain),var(--az-bar);box-shadow:inset 0 1px 0 #ffffff0d,0 1px 0 #000,0 2px 0 #3a3632,0 3px 0 #000;border-radius:2px 2px 0 0}
